import java.text.Normalizer;
import java.util.EnumSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.function.Predicate;
import java.util.regex.Pattern;

/**
 * Narrows the customer list by name and status.
 *
 * <p>A customer matches when it satisfies both parts:
 * <ul>
 *   <li>{@code name}: the text is split on whitespace into terms, and every term
 *       must appear, ignoring case and accents, in the customer's first name or
 *       last name. An empty name matches everyone.</li>
 *   <li>{@code statuses}: the customer's status must be one of these. An empty
 *       set matches every status.</li>
 * </ul>
 *
 * @param name     the name text as typed; may be empty or {@code null}
 * @param statuses the statuses to show; empty means all of them
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    /** The filter that matches every customer. */
    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());

    private static final Pattern WHITESPACE = Pattern.compile("\\s+", Pattern.UNICODE_CHARACTER_CLASS);
    private static final Pattern COMBINING_MARKS = Pattern.compile("\\p{M}+");

    public CustomerFilter {
        name = (name == null) ? "" : name;
        statuses = Set.copyOf(statuses);
    }

    /** Returns the filter as a predicate. Terms are normalised once, not per customer. */
    public Predicate<Customer> toPredicate() {
        List<String> terms = nameTerms();
        return customer -> (statuses.isEmpty() || statuses.contains(customer.status()))
                && terms.stream().allMatch(term ->
                        fold(customer.firstName()).contains(term)
                                || fold(customer.lastName()).contains(term));
    }

    private List<String> nameTerms() {
        return WHITESPACE.splitAsStream(name.strip())
                .filter(term -> !term.isEmpty())
                .map(CustomerFilter::fold)
                .toList();
    }

    /** Lower-cases and strips accents, so that {@code Mäkinen} folds to {@code makinen}. */
    private static String fold(String text) {
        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
        return COMBINING_MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
    }

    /** The statuses in declaration order, as used in the URL. */
    public Set<CustomerStatus> orderedStatuses() {
        return EnumSet.copyOf(statuses.isEmpty() ? EnumSet.noneOf(CustomerStatus.class) : statuses);
    }
}
