+import org.junit.jupiter.api.BeforeAll;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+
+/**
+ * Drives the running application in a real, offline headless Chromium. It checks
+ * what the browser can see and the browser cannot be checked by Karibu: the
+ * address bar, and how many queries typing costs the backend.
+ */
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class CustomerListBrowserTest {
+
+    private static Playwright playwright;
+    private static Browser browser;
+
+    @LocalServerPort
+    private int port;
+
+    @Autowired
+    private QueryLog queryLog;
+
+    @BeforeAll
+    static void launchBrowser() {
+        playwright = Playwright.create();
+        browser = playwright.chromium().launch(new BrowserType.LaunchOptions().setHeadless(true));
+    }
+
+    @AfterAll
+    static void closeBrowser() {
+        browser.close();
+        playwright.close();
+    }
+
+    @Test
+    void urlFiltersArePresentedInTheFieldsAndTheSummary() {
+        try (Page page = browser.newPage()) {
+            page.navigate(url("/?name=vir&status=ACTIVE,CLOSED"));
+
+            assertEquals("vir", filterInput(page).inputValue());
+            assertEquals("Showing 10 of 500", summary(page).textContent());
+        }
+    }
+
+    @Test
+    void typingNarrowsTheListAndWritesTheUrlWithoutNewHistoryEntries() {
+        try (Page page = browser.newPage()) {
+            page.navigate(url("/"));
+            waitForSummary(page, "Showing 500 of 500");
+
+            int historyBefore = ((Number) page.evaluate("history.length")).intValue();
+            queryLog.clear();
+            Locator input = filterInput(page);
+            input.click();
+            input.pressSequentially("makinen", new Locator.PressSequentiallyOptions().setDelay(40));
+            waitForSummary(page, "Showing 15 of 500");
+            page.waitForURL(url -> url.contains("name=makinen"));
+
+            assertFalse(page.url().contains("status="), "address bar was " + page.url());
+            assertEquals(historyBefore, ((Number) page.evaluate("history.length")).intValue(),
+                    "typing must not add history entries");
+            assertTrue(queryLog.countQueries().size() <= 2,
+                    "typing nine letters asked for the count " + queryLog.countQueries().size() + " times");
+            assertTrue(queryLog.pageQueries().size() <= 4,
+                    "typing nine letters asked for " + queryLog.pageQueries().size() + " pages");
+        }
+    }
+
+    @Test
+    void clearingTheFilterLeavesNoParametersInTheAddressBar() {
+        try (Page page = browser.newPage()) {
+            page.navigate(url("/?name=vir"));
+            waitForSummary(page, "Showing 15 of 500");
+
+            filterInput(page).fill("");
+            waitForSummary(page, "Showing 500 of 500");
+            page.waitForURL(url -> !url.contains("name="));
+
+            assertFalse(page.url().contains("name="), "address bar was " + page.url());
+            assertFalse(page.url().contains("status="), "address bar was " + page.url());
+        }
+    }
+
+    @Test
+    void selectingStatusesUpdatesTheAddressBar() {
+        try (Page page = browser.newPage()) {
+            page.navigate(url("/"));
+            waitForSummary(page, "Showing 500 of 500");
+
+            page.locator("vaadin-multi-select-combo-box").click();
+            page.locator("vaadin-multi-select-combo-box-item").filter(
+                    new Locator.FilterOptions().setHasText("CLOSED")).click();
+            page.keyboard().press("Escape");
+            page.waitForURL(url -> url.contains("status=CLOSED"));
+            waitForSummary(page, "Showing 166 of 500");
+        }
+    }
+
+    private String url(String path) {
+        return URI.create("http://localhost:" + port).resolve(path).toString();
+    }
+
+    private static Locator filterInput(Page page) {
+        return page.locator("input[placeholder='Filter by name']");
+    }
+
+    private static Locator summary(Page page) {
+        return page.locator("span").filter(new Locator.FilterOptions().setHasText("Showing "));
+    }
+
+    private static void waitForSummary(Page page, String text) {
+        summary(page).filter(new Locator.FilterOptions().setHasText(text))
+                .waitFor(new Locator.WaitForOptions().setState(WaitForSelectorState.ATTACHED));
+    }
+}
