+package com.example.customers.domain;
+
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.Set;
+
+import org.junit.jupiter.api.Test;
+
+class CustomerFilterTest {
+
+    private static final Customer ADA = new Customer(
+            1, "Ada", "Aaltonen", "ada@example.com", "Finland", CustomerStatus.ACTIVE);
+    private static final Customer JOSEPHINE = new Customer(
+            2, "Joséphine", "Mäkinen", "j@example.com", "France", CustomerStatus.PENDING);
+
+    private static boolean matches(CustomerFilter filter, Customer customer) {
+        return filter.toPredicate().test(customer);
+    }
+
+    @Test
+    void emptyFilterMatchesEveryone() {
+        assertTrue(matches(CustomerFilter.NONE, ADA));
+        assertTrue(matches(new CustomerFilter("   ", Set.of()), JOSEPHINE));
+        assertTrue(matches(new CustomerFilter(null, Set.of()), JOSEPHINE));
+    }
+
+    @Test
+    void everyTermMustMatchTheFirstOrLastName() {
+        assertTrue(matches(new CustomerFilter("ada aal", Set.of()), ADA));
+        assertTrue(matches(new CustomerFilter("aal ada", Set.of()), ADA));
+        assertFalse(matches(new CustomerFilter("ada virtanen", Set.of()), ADA));
+    }
+
+    @Test
+    void whitespaceIsNotSignificant() {
+        assertTrue(matches(new CustomerFilter("  ada \t  aal  ", Set.of()), ADA));
+    }
+
+    @Test
+    void caseAndAccentsAreIgnoredInBothDirections() {
+        assertTrue(matches(new CustomerFilter("makinen", Set.of()), JOSEPHINE));
+        assertTrue(matches(new CustomerFilter("MAKINEN", Set.of()), JOSEPHINE));
+        assertTrue(matches(new CustomerFilter("mäkinen", Set.of()), JOSEPHINE));
+        assertTrue(matches(new CustomerFilter("josephine", Set.of()), JOSEPHINE));
+    }
+
+    @Test
+    void statusFilterKeepsOnlySelectedStatuses() {
+        assertTrue(matches(new CustomerFilter("", Set.of(CustomerStatus.ACTIVE)), ADA));
+        assertFalse(matches(new CustomerFilter("", Set.of(CustomerStatus.CLOSED)), ADA));
+        assertTrue(matches(new CustomerFilter("", Set.of(CustomerStatus.CLOSED, CustomerStatus.PENDING)), JOSEPHINE));
+    }
+
+    @Test
+    void bothFiltersMustPass() {
+        assertFalse(matches(new CustomerFilter("ada", Set.of(CustomerStatus.CLOSED)), ADA));
+        assertTrue(matches(new CustomerFilter("ada", Set.of(CustomerStatus.ACTIVE)), ADA));
+    }
+}
